from functools import lru_cache

# --- Option 1: @lru_cache (cleanest for pure functions) ---
@lru_cache(maxsize=None)
def fib(n: int) -> int:
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(50))   # instant; without cache this would take centuries

# --- Option 2: Explicit memo dict (useful when state is complex) ---
def coin_ways(coins: tuple[int, ...], amount: int) -> int:
    memo: dict[int, int] = {}

    def dp(remaining: int) -> int:
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        if remaining in memo:
            return memo[remaining]
        total = sum(dp(remaining - c) for c in coins)
        memo[remaining] = total
        return total

    return dp(amount)

print(coin_ways((1, 2, 5), 5))   # 4 ways

# --- When @lru_cache won't work ---
# - Mutable arguments (lists, dicts) — convert to tuples
# - State involving external structures — use explicit memo
# - Multi-parameter state — @lru_cache still works: def dp(i, j, k)

# Fibonacci — tabulation
def fib_tab(n: int) -> int:
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

print(fib_tab(50))  # 12586269025

# Climbing stairs: dp[i] = ways to reach stair i
# (can take 1 or 2 steps at a time)
def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]   # same recurrence as Fibonacci!
    return dp[n]

print(climb_stairs(10))  # 89

# Coin change (minimum coins) — 2D tabulation idea, 1D in practice
def min_coins(coins: list[int], amount: int) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != float('inf') else -1

print(min_coins([1, 5, 6, 9], 11))  # 2 (9 + ... no, 6+5=11 → 2 coins)

# Stage 1: Naive recursion — O(2^n) time, O(n) stack space
def fib_naive(n: int) -> int:
    if n <= 1:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)
# fib_naive(40) takes ~1 second; fib_naive(60) takes hours

# Stage 2: Memoization — O(n) time, O(n) space
from functools import cache

@cache
def fib_memo(n: int) -> int:
    if n <= 1:
        return n
    return fib_memo(n - 1) + fib_memo(n - 2)
# fib_memo(1000) is instant

# Stage 3: Tabulation — O(n) time, O(n) space
def fib_tab(n: int) -> int:
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

# Stage 4: Space-optimized — O(n) time, O(1) space
# Only the last two values matter; discard the rest
def fib_opt(n: int) -> int:
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

print(fib_opt(100))  # 354224848179261915075

def knapsack_01(
    weights: list[int], values: list[int], capacity: int
) -> int:
    n = len(weights)
    # dp[i][c] = max value using first i items with capacity c
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        w, v = weights[i - 1], values[i - 1]
        for c in range(capacity + 1):
            # Option 1: skip item i
            dp[i][c] = dp[i - 1][c]
            # Option 2: take item i (only if it fits)
            if w <= c:
                dp[i][c] = max(dp[i][c], dp[i - 1][c - w] + v)

    return dp[n][capacity]

# Space-optimized: 1D array (iterate capacity in reverse)
def knapsack_01_1d(
    weights: list[int], values: list[int], capacity: int
) -> int:
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        # Iterate RIGHT TO LEFT to avoid using the same item twice
        for c in range(capacity, w - 1, -1):
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[capacity]

# Example
weights = [2, 3, 4, 5]
values  = [3, 4, 5, 6]
capacity = 8
print(knapsack_01_1d(weights, values, capacity))  # 10 (items 1+3: wt=6, val=9 ... or 2+3: wt=7, val=10)

def lcs_length(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

print(lcs_length('ABCBDAB', 'BDCABA'))  # 4  (BCBA or BDAB)

# Reconstruct the actual LCS string by backtracking the table
def lcs_string(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    result = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            result.append(a[i - 1])
            i -= 1; j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return ''.join(reversed(result))

print(lcs_string('ABCBDAB', 'BDCABA'))  # BDAB (or BCBA)

# O(n²) DP approach
def lis_n2(nums: list[int]) -> int:
    n = len(nums)
    if not n:
        return 0
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

print(lis_n2([10, 9, 2, 5, 3, 7, 101, 18]))  # 4  ([2, 5, 7, 101])

# O(n log n) — patience sorting / binary search trick
import bisect

def lis_nlogn(nums: list[int]) -> int:
    # 'tails' stores the smallest tail element for increasing
    # subsequences of each length.
    # tails[i] = smallest possible tail of all LIS of length i+1
    tails: list[int] = []
    for num in nums:
        pos = bisect.bisect_left(tails, num)
        if pos == len(tails):
            tails.append(num)   # extend LIS by 1
        else:
            tails[pos] = num    # replace: maintain smallest tail
    return len(tails)

print(lis_nlogn([10, 9, 2, 5, 3, 7, 101, 18]))  # 4

# Note: 'tails' is NOT the actual LIS sequence.
# To reconstruct, use a parent array alongside the O(n²) approach.

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # dp[i][j] = edit distance between a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i   # delete all chars of a[:i]
    for j in range(n + 1):
        dp[0][j] = j   # insert all chars of b[:j]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]        # free match
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],     # delete from a
                    dp[i][j - 1],     # insert into a
                    dp[i - 1][j - 1]  # substitute
                )

    return dp[m][n]

print(edit_distance('kitten', 'sitting'))   # 3
# kitten → sitten (sub k→s) → sittin (sub e→i) → sitting (insert g)

print(edit_distance('horse', 'ros'))        # 3

# Space-optimized: only need previous row
def edit_distance_1d(a: str, b: str) -> int:
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j], curr[j - 1], prev[j - 1])
        prev = curr
    return prev[len(b)]

# Edit distance: 2D → 1D (rolling single row)
def edit_distance_opt(a: str, b: str) -> int:
    # prev[j] = edit_distance(a[:i], b[:j]) from previous i-iteration
    prev = list(range(len(b) + 1))   # base case: dp[0][j] = j

    for i, ca in enumerate(a, 1):
        curr = [i] + [0] * len(b)    # dp[i][0] = i
        for j, cb in enumerate(b, 1):
            if ca == cb:
                curr[j] = prev[j - 1]              # diagonal match
            else:
                curr[j] = 1 + min(
                    prev[j],       # delete
                    curr[j - 1],   # insert
                    prev[j - 1]    # substitute
                )
        prev = curr
    return prev[len(b)]

# LCS: 2D → 1D (need prev[j-1] before it's overwritten)
def lcs_opt(a: str, b: str) -> int:
    prev = [0] * (len(b) + 1)
    for ca in a:
        curr = [0] * (len(b) + 1)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr
    return prev[len(b)]

# 0/1 Knapsack: 2D → 1D (right-to-left to avoid re-using item)
def knapsack_opt(weights: list[int], values: list[int], W: int) -> int:
    dp = [0] * (W + 1)
    for w, v in zip(weights, values):
        for c in range(W, w - 1, -1):   # RIGHT to LEFT — crucial!
            dp[c] = max(dp[c], dp[c - w] + v)
    return dp[W]

# Tree DP: diameter of a binary tree
# diameter = max path length through any node (by edge count)
class TreeNode:
    def __init__(self, val: int = 0,
                 left: 'TreeNode | None' = None,
                 right: 'TreeNode | None' = None):
        self.val = val; self.left = left; self.right = right

def diameter_of_binary_tree(root: TreeNode | None) -> int:
    best = 0

    def depth(node: TreeNode | None) -> int:
        nonlocal best
        if not node:
            return 0
        left  = depth(node.left)    # post-order: children first
        right = depth(node.right)
        best  = max(best, left + right)   # path through this node
        return max(left, right) + 1       # depth of this subtree

    depth(root)
    return best

# DAG DP: longest path in a DAG
from functools import cache

def longest_path_dag(
    graph: dict[int, list[int]]
) -> int:
    @cache
    def dp(node: int) -> int:
        # Longest path starting from 'node'
        if not graph.get(node):
            return 0
        return 1 + max(dp(neighbor) for neighbor in graph[node])

    all_nodes = set(graph.keys()) | {v for vs in graph.values() for v in vs}
    return max(dp(node) for node in all_nodes) if all_nodes else 0
